// Keep a private immutable snapshot: mutating an exported object cannot silently
// redefine which performed pitches belong to these original-page images.
const reference = new Map(bumblebeeYeungNotation.notes.map(note => [note.noteId,
  Object.freeze([note.midi, note.beat, note.duration, note.hand])])) ;

/** True only for the complete, untransposed, unchanged 1,313-note edition. */
export function sourceNotationMatched(score) {
  if (!score || score.id !== 'bumblebee-yeung-complete' || score.durationBeats !== 210
      || score.keySignature !== 0 || score.timeSignature?.length !== 2
      || score.timeSignature[0] !== 2 || score.timeSignature[1] !== 4
      || !Array.isArray(score.notes) || score.notes.length !== reference.size) return false;
  const seen = new Set();
  for (const note of score.notes) {
    if (!note || seen.has(note.id)) return false;
    const expected = reference.get(note.id);
    if (!expected || note.midi !== expected[0] || note.beat !== expected[1]
        || note.duration !== expected[2] || note.hand !== expected[3]) return false;
    seen.add(note.id);
  }
  return true;
}
